#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define INF 1000000000
#define MAXN 210
#define MAXV (MAXN*MAXN+MAXN*2+10)
#define MAXE (MAXV*6)

typedef struct { int to, rev, cap; } edge;

edge pool[MAXE];
int pool_sz;
int head[MAXV], nxt[MAXE];

int level[MAXV], it[MAXV];

void add_edge(int from, int to, int cap) {
    pool[pool_sz] = (edge){to, pool_sz+1, cap};
    nxt[pool_sz] = head[from];
    head[from] = pool_sz++;
    pool[pool_sz] = (edge){from, pool_sz-1, 0};
    nxt[pool_sz] = head[to];
    head[to] = pool_sz++;
}

int bfs(int s, int t) {
    memset(level, -1, sizeof(level));
    int q[MAXV], front=0, back=0;
    level[s] = 0;
    q[back++] = s;
    while (front < back) {
        int v = q[front++];
        for (int e = head[v]; e != -1; e = nxt[e]) {
            if (pool[e].cap > 0 && level[pool[e].to] < 0) {
                level[pool[e].to] = level[v] + 1;
                q[back++] = pool[e].to;
            }
        }
    }
    return level[t] >= 0;
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = it[v]; i != -1; i = nxt[i]) {
        edge &e = pool[i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, t, f < e.cap ? f : e.cap);
            if (d > 0) {
                e.cap -= d;
                pool[e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0, f;
    while (bfs(s, t)) {
        memcpy(it, head, sizeof(it));
        while ((f = dfs(s, t, INF)) > 0) flow += f;
    }
    return flow;
}

