#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    int x, y, v;
} Jewel;

typedef struct {
    int type;   /* 0: x <= a, 1: x >= a, 2: y <= a, 3: y >= a */
    int a, b;
} Cond;

static int cmp_int(const void *p, const void *q) {
    int a = *(const int*)p, b = *(const int*)q;
    return (a > b) - (a < b);
}

static int lower_bound_int(int *arr, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

static int upper_bound_int(int *arr, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] <= x) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Jewel *jw = (Jewel*)malloc(sizeof(Jewel) * N);
    int *xs = (int*)malloc(sizeof(int) * N);
    int *ys = (int*)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) {
        scanf("%d %d %d", &jw[i].x, &jw[i].y, &jw[i].v);
        xs[i] = jw[i].x;
        ys[i] = jw[i].y;
    }

    Cond *cd = (Cond*)malloc(sizeof(Cond) * M);

    for (int i = 0; i < M; i++) {
        char s[8];
        scanf("%s %d %d", s, &cd[i].a, &cd[i].b);
        if (strcmp(s, "L") == 0) cd[i].type = 0;      /* x <= a */
        else if (strcmp(s, "R") == 0) cd[i].type = 1; /* x >= a */
        else if (strcmp(s, "D") == 0) cd[i].type = 2; /* y <= a */
        else cd[i].type = 3;                          /* y >= a */
    }

    qsort(xs, N, sizeof(int), cmp_int);
    qsort(ys, N, sizeof(int), cmp_int);

    int nx = 0, ny = 0;
    for (int i = 0; i < N; i++) {
        if (i == 0 || xs[i] != xs[i - 1]) xs[nx++] = xs[i];
        if (i == 0 || ys[i] != ys[i - 1]) ys[ny++] = ys[i];
    }

    /*
      Any feasible stolen set is determined by a rectangle:
      x in [xl, xr], y in [yl, yr]
      where xl/xr/yl/yr are chosen from compressed borders outside/at jewel coords.

      We enumerate all rectangles over compressed coordinate indices.
      For each rectangle, selected jewels are exactly those inside it.
      Then verify all constraints and maximize total value.

      This is intended for small N (as in the original problem).
    */

    int X = nx + 1; /* split positions: 0..nx */
    int Y = ny + 1; /* split positions: 0..ny */

    ll ans = 0;

    for (int li = 0; li < X; li++) {
        for (int ri = li; ri < X; ri++) {
            for (int dj = 0; dj < Y; dj++) {
                for (int uj = dj; uj < Y; uj++) {
                    ll sum = 0;
                    int ok = 1;

                    /* count selected jewels and also prefix/suffix counts for constraints */
                    int *sel = (int*)calloc(N, sizeof(int));
                    int total = 0;

                    for (int i = 0; i < N; i++) {
                        int xi = lower_bound_int(xs, nx, jw[i].x);
                        int yi = lower_bound_int(ys, ny, jw[i].y);
                        if (li <= xi && xi < ri && dj <= yi && yi < uj) {
                            sel[i] = 1;
                            total++;
                            sum += jw[i].v;
                        }
                    }

                    for (int k = 0; k < M && ok; k++) {
                        int cnt = 0;
                        if (cd[k].type == 0) {
                            for (int i = 0; i < N; i++) if (sel[i] && jw[i].x <= cd[k].a) cnt++;
                        } else if (cd[k].type == 1) {
                            for (int i = 0; i < N; i++) if (sel[i] && jw[i].x >= cd[k].a) cnt++;
                        } else if (cd[k].type == 2) {
                            for (int i = 0; i < N; i++) if (sel[i] && jw[i].y <= cd[k].a) cnt++;
                        } else {
                            for (int i = 0; i < N; i++) if (sel[i] && jw[i].y >= cd[k].a) cnt++;
                        }
                        if (cnt > cd[k].b) ok = 0;
                    }

                    if (ok && sum > ans) ans = sum;
                    free(sel);
                }
            }
        }
    }

    printf("%lld\n", ans);

    free(jw);
    free(xs);
    free(ys);
    free(cd);
    return 0;
}

