#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int to, rev;
    ll cap;
    Edge(int to, int rev, ll cap) : to(to), rev(rev), cap(cap) {}
};

struct Dinic {
    int n;
    vector<vector<Edge>> g;
    vector<int> level, it;

    Dinic(int n) : n(n), g(n), level(n), it(n) {}

    void addEdge(int fr, int to, ll cap) {
        g[fr].emplace_back(to, (int)g[to].size(), cap);
        g[to].emplace_back(fr, (int)g[fr].size() - 1, 0);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (auto &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    ll dfs(int v, int t, ll f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); i++) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                ll d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    ll maxflow(int s, int t) {
        ll flow = 0;
        const ll INF = (1LL << 60);
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            while (true) {
                ll f = dfs(s, t, INF);
                if (!f) break;
                flow += f;
            }
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<ll> x(N), y(N), w(N);
    vector<ll> xs, ys;
    xs.reserve(N);
    ys.reserve(N);

    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i] >> w[i];
        xs.push_back(x[i]);
        ys.push_back(y[i]);
    }

    struct Cond {
        char c;
        ll z;
        int k;
    };
    vector<Cond> conds(M);
    for (int i = 0; i < M; i++) {
        cin >> conds[i].c >> conds[i].z >> conds[i].k;
        if (conds[i].c == 'L' || conds[i].c == 'R') xs.push_back(conds[i].z);
        else ys.push_back(conds[i].z);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    int X = xs.size();
    int Y = ys.size();

    auto xid = [&](ll v) {
        return (int)(lower_bound(xs.begin(), xs.end(), v) - xs.begin());
    };
    auto yid = [&](ll v) {
        return (int)(lower_bound(ys.begin(), ys.end(), v) - ys.begin());
    };

    // Build capacities for chains.
    // For x-prefix counts:
    // let A[i] = max allowed among jewels with x <= xs[i]
    // similarly for y-prefix counts.
    const ll INF = (1LL << 60);

    vector<ll> limX(X, (ll)N), limY(Y, (ll)N);

    for (auto &cd : conds) {
        if (cd.c == 'L') {
            int p = upper_bound(xs.begin(), xs.end(), cd.z) - xs.begin() - 1;
            if (p >= 0) limX[p] = min(limX[p], (ll)cd.k);
        } else if (cd.c == 'D') {
            int p = upper_bound(ys.begin(), ys.end(), cd.z) - ys.begin() - 1;
            if (p >= 0) limY[p] = min(limY[p], (ll)cd.k);
        }
    }

    // Prefix minima to make constraints monotone.
    for (int i = 1; i < X; i++) limX[i] = min(limX[i], limX[i - 1] + (ll)N);
    for (int i = 1; i < Y; i++) limY[i] = min(limY[i], limY[i - 1] + (ll)N);

    // Handle R and U by converting to lower bounds on prefixes:
    // count(x >= z) <= k  <=> total_selected - count(x < z) <= k
    // impossible to encode directly as standalone prefix cap without total variable.
    // Standard closure formulation uses suffix nodes too.
    // So we build two-dimensional closure with x-prefix and y-prefix selections:
    // A jewel selected implies selecting its x-index and y-index.
    // Constraints become capacities on consecutive differences for prefix/suffix chains.

    // We'll use the known reduction:
    // choose a downward-closed set in bipartite poset of x-prefix and y-prefix.
    // For each jewel at (ix,iy) with value w, add profit edge from Xnode(ix) to Ynode(iy).
    // Minimum cut on this graph with chain capacities gives maximum weight set
    // satisfying row/column cardinality constraints.
    //
    // To support all 4 directions, convert:
    // L x k : among x<=x0 at most k
    // R x k : among x>=x0 at most k
    // D y k : among y<=y0 at most k
    // U y k : among y>=y0 at most k
    //
    // This is equivalent to weighted maximum independent set in convex bipartite graph,
    // solved by min-cut on intervals of x and y ranks.
    //
    // We model each jewel as interval [ix, X-1] on x-suffix side and [iy, Y-1] on y-suffix side.
    // Simpler implementation: brute-force all distinct x/y compressed positions into 4 prefix systems.

    // Nodes:
    // 0..X-1 : x-prefix
    // X..X+X-1 : x-suffix
    // 2X..2X+Y-1 : y-prefix
    // 2X+Y..2X+2Y-1 : y-suffix
    // jewel nodes
    int baseXP = 0;
    int baseXS = baseXP + X;
    int baseYP = baseXS + X;
    int baseYS = baseYP + Y;
    int baseJ = baseYS + Y;
    int S = baseJ + N;
    int T = S + 1;

    Dinic mf(T + 1);

    ll total = 0;

    // Chain for x-prefix selected counts
    // capacity increments represent how many jewels can newly appear when extending prefix.
    vector<ll> capXP(X, (ll)N);
    for (int i = 0; i < X; i++) capXP[i] = limX[i] - (i ? limX[i - 1] : 0);
    for (int i = 0; i < X; i++) {
        if (capXP[i] < 0) {
            cout << 0 << '\n';
            return 0;
        }
        mf.addEdge(S, baseXP + i, capXP[i]);
        if (i + 1 < X) mf.addEdge(baseXP + i, baseXP + i + 1, INF);
    }

    vector<ll> limXSuf(X, (ll)N);
    for (auto &cd : conds) if (cd.c == 'R') {
        int p = lower_bound(xs.begin(), xs.end(), cd.z) - xs.begin();
        if (p < X) limXSuf[p] = min(limXSuf[p], (ll)cd.k);
    }
    for (int i = X - 2; i >= 0; i--) limXSuf[i] = min(limXSuf[i], limXSuf[i + 1] + (ll)N);
    vector<ll> capXS(X, 0);
    for (int i = X - 1; i >= 0; i--) {
        ll nxt = (i + 1 < X ? limXSuf[i + 1] : 0);
        capXS[i] = limXSuf[i] - nxt;
    }
    for (int i = X - 1; i >= 0; i--) {
        if (capXS[i] < 0) {
            cout << 0 << '\n';
            return 0;
        }
        mf.addEdge(S, baseXS + i, capXS[i]);
        if (i - 1 >= 0) mf.addEdge(baseXS + i, baseXS + i - 1, INF);
    }

    vector<ll> limYP(Y, (ll)N);
    for (auto &cd : conds) if (cd.c == 'D') {
        int p = upper_bound(ys.begin(), ys.end(), cd.z) - ys.begin() - 1;
        if (p >= 0) limYP[p] = min(limYP[p], (ll)cd.k);
    }
    vector<ll> capYP(Y, 0);
    for (int i = 0; i < Y; i++) capYP[i] = limYP[i] - (i ? limYP[i - 1] : 0);
    for (int i = 0; i < Y; i++) {
        if (capYP[i] < 0) {
            cout << 0 << '\n';
            return 0;
        }
        mf.addEdge(baseYP + i, T, capYP[i]);
        if (i + 1 < Y) mf.addEdge(baseYP + i + 1, baseYP + i, INF);
    }

    vector<ll> limYSuf(Y, (ll)N);
    for (auto &cd : conds) if (cd.c == 'U') {
        int p = lower_bound(ys.begin(), ys.end(), cd.z) - ys.begin();
        if (p < Y) limYSuf[p] = min(limYSuf[p], (ll)cd.k);
    }
    for (int i = Y - 2; i >= 0; i--) limYSuf[i] = min(limYSuf[i], limYSuf[i + 1] + (ll)N);
    vector<ll> capYS(Y, 0);
    for (int i = Y - 1; i >= 0; i--) {
        ll nxt = (i + 1 < Y ? limYSuf[i + 1] : 0);
        capYS[i] = limYSuf[i] - nxt;
    }
    for (int i = 0; i < Y; i++) {
        if (capYS[i] < 0) {
            cout << 0 << '\n';
            return 0;
        }
        mf.addEdge(baseYS + i, T, capYS[i]);
        if (i + 1 < Y) mf.addEdge(baseYS + i, baseYS + i + 1, INF);
    }

    for (int i = 0; i < N; i++) {
        int ix = xid(x[i]);
        int iy = yid(y[i]);
        int jv = baseJ + i;
        total += w[i];

        mf.addEdge(S, jv, w[i]);

        // If jewel is chosen, it consumes one unit from all four relevant systems.
        mf.addEdge(jv, baseXP + ix, INF);
        mf.addEdge(jv, baseXS + ix, INF);
        mf.addEdge(baseYP + iy, jv, INF);
        mf.addEdge(baseYS + iy, jv, INF);
    }

    ll cut = mf.maxflow(S, T);
    cout << total - cut << '\n';
    return 0;
}

