        int to, rev;
        long cap;
        Edge(int to, int rev, long cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static List<Edge>[] graph;
    static int[] level, iter;

    static void addEdge(int from, int to, long cap) {
        graph[from].add(new Edge(to, graph[to].size(), cap));
        graph[to].add(new Edge(from, graph[from].size() - 1, 0));
    }

    static void bfs(int s) {
        Arrays.fill(level, -1);
        Queue<Integer> q = new LinkedList<>();
        level[s] = 0;
        q.add(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : graph[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.add(e.to);
                }
            }
        }
    }

    static long dfs(int v, int t, long f) {
        if (v == t) return f;
        for (int i = iter[v]; i < graph[v].size(); i++) {
            Edge e = graph[v].get(i);
            if (e.cap > 0 && level[v] < level[e.to]) {
                long d = dfs(e.to, t, Math.min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    graph[e.to].get(e.rev).cap += d;
                    return d;
                }
            }
            iter[v]++;
        }
        return 0;
    }

    static long maxFlow(int s, int t) {
        long flow = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;
            Arrays.fill(iter, 0);
            long f;
            while ((f = dfs(s, t, Long.MAX_VALUE)) > 0) {
                flow += f;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int N = Integer.parseInt(parts[0]);
        int M = Integer.parseInt(parts[1]);

        int[] x = new int[N];
        int[] y = new int[N];
        long[] v = new long[N];
        long total = 0;
        for (int i = 0; i < N; i++) {
            parts = br.readLine().split(" ");
            x[i] = Integer.parseInt(parts[0]);
            y[i] = Integer.parseInt(parts[1]);
            v[i] = Long.parseLong(parts[2]);
            total += v[i];
        }

        Map<Integer, Integer> xId = new HashMap<>();
        Map<Integer, Integer> yId = new HashMap<>();
        int xCnt = 0, yCnt = 0;

        for (int i = 0; i < N; i++) {
            if (!xId.containsKey(x[i])) xId.put(x[i], xCnt++);
            if (!yId.containsKey(y[i])) yId.put(y[i], yCnt++);
        }

        int S = 0;
        int T = 1;
        int nodeId = 2;
        int jewelStart = nodeId;
        nodeId += N;
        int xCondStart = nodeId;
        nodeId += xCnt;
        int yCondStart = nodeId;
        nodeId += yCnt;

        graph = new ArrayList[nodeId];
        for (int i = 0; i < nodeId; i++) graph[i] = new ArrayList<>();
        level = new int[nodeId];
        iter = new int[nodeId];

        // read conditions
        long[] xLimit = new long[xCnt];
        long[] yLimit = new long[yCnt];
        Arrays.fill(xLimit, Long.MAX_VALUE);
        Arrays.fill(yLimit, Long.MAX_VALUE);

        for (int i = 0; i < M; i++) {
            parts = br.readLine().split(" ");
            String type = parts[0];
            int a = Integer.parseInt(parts[1]);
            long b = Long.parseLong(parts[2]);
            if (type.equals("x")) {
                int id = xId.get(a);
                xLimit[id] = Math.min(xLimit[id], b);
            } else {
                int id = yId.get(a);
                yLimit[id] = Math.min(yLimit[id], b);
            }
        }

        // source -> x condition
        for (int i = 0; i < xCnt; i++) {
            if (xLimit[i] < Long.MAX_VALUE) {
                addEdge(S, xCondStart + i, xLimit[i]);
            } else {
                addEdge(S, xCondStart + i, total);
            }
        }

        // x condition -> jewel
        for (int i = 0; i < N; i++) {
            int xi = xId.get(x[i]);
            addEdge(xCondStart + xi, jewelStart + i, Long.MAX_VALUE);
        }

        // jewel -> y condition
        for (int i = 0; i < N; i++) {
            int yi = yId.get(y[i]);
            addEdge(jewelStart + i, yCondStart + yi, Long.MAX_VALUE);
        }

        // y condition -> sink
        for (int i = 0; i < yCnt; i++) {
            if (yLimit[i] < Long.MAX_VALUE) {
                addEdge(yCondStart + i, T, yLimit[i]);
            } else {
                addEdge(yCondStart + i, T, total);
            }
        }

        long minCut = maxFlow(S, T);
        System.out.println(total - minCut);
    }
}

