public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Dinic {
        static class Edge {
            int to, rev;
            long cap;
            Edge(int to, int rev, long cap) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
            }
        }

        int n;
        ArrayList<Edge>[] g;
        int[] level, it;

        @SuppressWarnings("unchecked")
        Dinic(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, long cap) {
            Edge f = new Edge(to, g[to].size(), cap);
            Edge r = new Edge(fr, g[fr].size(), 0);
            g[fr].add(f);
            g[to].add(r);
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                Edge e = g[v].get(it[v]);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        g[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long flow = 0;
            long INF = Long.MAX_VALUE / 4;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, t, INF)) > 0) flow += f;
            }
            return flow;
        }
    }

    static class Jewel {
        long x, y, v;
        Jewel(long x, long y, long v) {
            this.x = x; this.y = y; this.v = v;
        }
    }

    static class Cond {
        int type; // 1: x, 2: y
        long a;
        long b;
        Cond(int type, long a, long b) {
            this.type = type; this.a = a; this.b = b;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        Jewel[] jewels = new Jewel[N];
        ArrayList<Long> xs = new ArrayList<>();
        ArrayList<Long> ys = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            long v = fs.nextLong();
            jewels[i] = new Jewel(x, y, v);
            xs.add(x);
            ys.add(y);
        }

        Cond[] conds = new Cond[M];
        for (int i = 0; i < M; i++) {
            int t = fs.nextInt();
            long a = fs.nextLong();
            long b = fs.nextLong();
            conds[i] = new Cond(t, a, b);
            if (t == 1) xs.add(a);
            else ys.add(a);
        }

        long[] xVals = compress(xs);
        long[] yVals = compress(ys);
        int px = xVals.length;
        int py = yVals.length;

        long[] limX = new long[px];
        long[] limY = new long[py];
        Arrays.fill(limX, N);
        Arrays.fill(limY, N);

        for (Cond c : conds) {
            if (c.type == 1) {
                int id = upperBound(xVals, c.a) - 1;
                if (id >= 0) limX[id] = Math.min(limX[id], c.b);
            } else {
                int id = upperBound(yVals, c.a) - 1;
                if (id >= 0) limY[id] = Math.min(limY[id], c.b);
            }
        }

        for (int i = 1; i < px; i++) limX[i] = Math.min(limX[i], limX[i - 1] + countEqualX(jewels, xVals[i]));
        for (int i = 1; i < px; i++) limX[i] = Math.min(limX[i], limX[i - 1] + N);
        for (int i = 1; i < px; i++) limX[i] = Math.max(limX[i], limX[i - 1]);
        for (int i = 1; i < py; i++) limY[i] = Math.min(limY[i], limY[i - 1] + countEqualY(jewels, yVals[i]));
        for (int i = 1; i < py; i++) limY[i] = Math.min(limY[i], limY[i - 1] + N);
        for (int i = 1; i < py; i++) limY[i] = Math.max(limY[i], limY[i - 1]);

        long[] dx = new long[px];
        long[] dy = new long[py];
        if (px > 0) dx[0] = limX[0];
        for (int i = 1; i < px; i++) dx[i] = limX[i] - limX[i - 1];
        if (py > 0) dy[0] = limY[0];
        for (int i = 1; i < py; i++) dy[i] = limY[i] - limY[i - 1];

        long INF = (long) 4e18;

        int S = 0;
        int xBase = 1;
        int yBase = xBase + px;
        int T = yBase + py;
        Dinic dinic = new Dinic(T + 1);

        for (int i = 0; i < px; i++) {
            dinic.addEdge(S, xBase + i, dx[i]);
            if (i > 0) dinic.addEdge(xBase + i, xBase + i - 1, INF);
        }
        for (int j = 0; j < py; j++) {
            dinic.addEdge(yBase + j, T, dy[j]);
            if (j > 0) dinic.addEdge(yBase + j - 1, yBase + j, INF);
        }

        long total = 0;
        for (Jewel jw : jewels) {
            int ix = lowerBound(xVals, jw.x);
            int iy = lowerBound(yVals, jw.y);
            dinic.addEdge(xBase + ix, yBase + iy, jw.v);
            total += jw.v;
        }

        long minCut = dinic.maxFlow(S, T);
        long ans = total - minCut;
        System.out.println(ans);
    }

    static long[] compress(ArrayList<Long> list) {
        long[] a = new long[list.size()];
        for (int i = 0; i < list.size(); i++) a[i] = list.get(i);
        Arrays.sort(a);
        int m = 0;
        for (int i = 0; i < a.length; i++) {
            if (i == 0 || a[i] != a[i - 1]) a[m++] = a[i];
        }
        return Arrays.copyOf(a, m);
    }

    static int lowerBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] < x) l = m + 1;
            else r = m;
        }
        return l;
    }

    static int upperBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] <= x) l = m + 1;
            else r = m;
        }
        return l;
    }

    static long countEqualX(Jewel[] jewels, long x) {
        long c = 0;
        for (Jewel j : jewels) if (j.x == x) c++;
        return c;
    }

    static long countEqualY(Jewel[] jewels, long y) {
        long c = 0;
        for (Jewel j : jewels) if (j.y == y) c++;
        return c;
    }
}
